package ai.interviewiq.api.config;
import ai.interviewiq.api.entity.*; import ai.interviewiq.api.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
/** Test profile mirrors the selectable production catalog; Flyway owns MySQL data. */
@Configuration @Profile("test") public class ReferenceDataConfiguration { @Bean CommandLineRunner referenceData(CompanyRepository c,JobRoleRepository r,DifficultyLevelRepository d,InterviewTemplateRepository t){return a->{if(c.count()!=0)return;
for(String[] x:new String[][]{{"GOOGLE","Google"},{"AMAZON","Amazon"},{"MICROSOFT","Microsoft"},{"META","Meta"},{"APPLE","Apple"},{"NETFLIX","Netflix"},{"TCS","TCS"},{"INFOSYS","Infosys"},{"WIPRO","Wipro"},{"ACCENTURE","Accenture"},{"DELOITTE","Deloitte"},{"IBM","IBM"},{"CAPGEMINI","Capgemini"}})c.save(new Company(x[0],x[1]));
for(String[] x:new String[][]{{"SOFTWARE_ENGINEER","Software Engineer","Engineering"},{"JAVA_DEVELOPER","Java Developer","Engineering"},{"PYTHON_DEVELOPER","Python Developer","Engineering"},{"FRONTEND_DEVELOPER","Frontend Developer","Engineering"},{"BACKEND_DEVELOPER","Backend Developer","Engineering"},{"FULL_STACK_DEVELOPER","Full Stack Developer","Engineering"},{"DATA_ANALYST","Data Analyst","Data"},{"DATA_SCIENTIST","Data Scientist","Data"},{"MACHINE_LEARNING_ENGINEER","Machine Learning Engineer","Data"},{"DEVOPS_ENGINEER","DevOps Engineer","Infrastructure"},{"CLOUD_ENGINEER","Cloud Engineer","Infrastructure"},{"CYBERSECURITY_ANALYST","Cybersecurity Analyst","Security"},{"DATABASE_DEVELOPER","Database Developer","Engineering"},{"QA_ENGINEER","QA Engineer","Engineering"},{"BUSINESS_ANALYST","Business Analyst","Business"}})r.save(new JobRole(x[0],x[1],x[2]));
d.save(new DifficultyLevel("EASY","Easy",1));d.save(new DifficultyLevel("MEDIUM","Medium",2));d.save(new DifficultyLevel("HARD","Hard",3));d.save(new DifficultyLevel("EXPERT","Expert",4));t.save(new InterviewTemplate("GENERAL","General Interview",5));t.save(new InterviewTemplate("TECHNICAL","Technical Interview",5));t.save(new InterviewTemplate("BEHAVIORAL","Behavioral Interview",5));};} }
